-- self-promote to reviewed for this slice's rows
update public.meme_translations t
set status = 'reviewed', reviewed_at = now(), reviewed_by = 'c7295ec1-1ca9-414d-a7e1-8f19005a90d0'::uuid
from public.memes m
where t.meme_id = m.id
  and t.locale = 'ja'
