values
  ('e9a948ba-be09-45f7-9dc4-22f42124c27a', 'ja', 'romgok-opnup-hangul-flip', '롬곡옾눞(ハングル反転パロディ)', '「暴風の涙(폭풍눈물)」という文字を上下逆さまに書くとこう見える、というハングルの視覚的言葉遊び。', '「暴風の涙(폭풍눈물、号泣の意)」という文字列を上下反転させると「롬곡옾눞」のように見えることから生まれた言葉遊びのミームである。2018年頃、韓国のオンラインコミュニティでハングルの珍しい反転現象として話題になった。', 'ハングルの字母を上下反転させる遊びの中で発見され、コミュニティで共有されて広まった', '悲しい場面や涙が出る状況をユーモラスに表現する際に使う', NULL, array['롬곡옾높', '暴風の涙(反転前の言葉)', '롬곡옾눞']::text[], '[{"text": "試験ダメだった…롬곡옾눞", "situation": "カカオトーク"}, {"text": "この結果見て롬곡옾눞だわ", "situation": "SNSコメント"}]'::jsonb, 'machine', '2026-07-15T15:30:00.191373+00:00', 'claude', 'claude-fable-5', 12, now(), null, null)
insert into public.meme_translations
  (meme_id, locale, localized_slug, title, summary, description, origin, usage_note, caution, aliases, usage_examples, status, source_updated_at, provider, model, prompt_version, translated_at, reviewed_at, reviewed_by)
values
  ('4f7cf03a-7cc5-4e2f-ac5e-3a15f5dd0180', 'ja', 'hyeongnim-meonjeo-au-meonjeo', '兄さんお先に、弟お先に(農心ラーメンCM)', '1970年代のオリジナルCMを2005年にソ・ギョンソク&イ・ユンソクのコンビでリメイクした農心ラーメンのキャッチコピー。', '1975年、ク・ボンソとクァク・ギュソクが出演した農心ラーメンCMの「兄さんお先に、弟お先に」というキャッチコピーは、2005年の農心創立40周年を機にソ・ギョンソクとイ・ユンソクのコンビでリメイクされた。懐かしのラーメンを再発売するにあたり、当時の雰囲気を蘇らせる広告として企画された。互いに譲り合う美徳を表す言葉として、現在も幅広く引用されている。', '2005年、農心ユッケジャンラーメンのテレビCM。ソ・ギョンソク、イ・ユンソク出演のリメイク版。', '互いに譲り合う場面で「兄さんお先に、弟お先に」を引用する', NULL, array['ソ・ギョンソク&イ・ユンソクのユッケジャンCM', '형님먼저 아우먼저']::text[], '[]'::jsonb, 'machine', '2026-07-15T15:30:00.191373+00:00', 'claude', 'claude-fable-5', 12, now(), null, null)
insert into public.meme_translations
