values
  ('f3060027-cdd8-4236-893a-15e438c992fb', 'ja', 'n-split-vlog', 'N分割Vlog', '会社員など異なる暮らしを送る複数人の一日を画面分割で見せるリール形式。', '画面を複数のコマに分割し、会社員、ワーホリ、就活生、看護師、公務員などそれぞれ異なる一日を過ごす人々の様子を1本の動画にまとめて見せるリール形式である。互いに異なる生活のルーティンや撮影構図を見比べる面白さから、2025年にInstagramで流行した。', '2025年にInstagramリールで登場したマルチ画面Vlogのトレンドで、その年の人気リールフォーマットの一つとして紹介された。', '友人同士でそれぞれの一日のルーティン(出勤、ワーホリ、就活など)を見比べて一緒に投稿する際に使う', NULL, array['マルチVlogチャレンジ', 'N분할 브이로그']::text[], '[]'::jsonb, 'machine', '2026-07-15T15:30:00.191373+00:00', 'claude', 'claude-fable-5', 12, now(), null, null)
insert into public.meme_translations
  (meme_id, locale, localized_slug, title, summary, description, origin, usage_note, caution, aliases, usage_examples, status, source_updated_at, provider, model, prompt_version, translated_at, reviewed_at, reviewed_by)
values
  ('fefce520-c551-46fc-963d-e9e527e02392', 'ja', 'seo-taiji-i-know', 'ソテジワアイドゥル「I Know(僕は知ってる)」', 'ソテジワアイドゥルのデビュー曲で、審査員の酷評の中で始まった大衆文化の大革命。', '1992年3月に発売されたソテジワアイドゥルのデビュー曲。MBC「特種TV演芸」の新人ステージで審査員団から平均7.8点という歴代最低点を受けたが、その後10代の若者たちの間で爆発的な反響を呼び、韓国大衆音楽の勢力図を変えた象徴的な出来事となった。「酷評からの大逆転」の元祖的なミームとして、今もオーディション番組などで語り継がれている。', '1992年3月、ソテジワアイドゥル1集発売。同年4月11日、MBC「特種TV演芸」でデビューステージ。', '酷評を受けながらも結果的に成功した事例を語る際に引用される', NULL, array['ソテジワアイドゥル1集', '난알아요', '난 알아요']::text[], '[{"text": "今回の企画、最初はみんな微妙って言ってたのに上手くいってるの見ると完全に「I Know」案件だね", "situation": "会社のチャット"}, {"text": "オーディションで酷評されても結局バズるの、完全にソテジの「I Know」シーズン2じゃない?", "situation": "友達とのトーク"}]'::jsonb, 'machine', '2026-07-15T15:30:00.191373+00:00', 'claude', 'claude-fable-5', 12, now(), null, null)
insert into public.meme_translations
  (meme_id, locale, localized_slug, title, summary, description, origin, usage_note, caution, aliases, usage_examples, status, source_updated_at, provider, model, prompt_version, translated_at, reviewed_at, reviewed_by)
values
  ('f4db1c4f-832f-41df-acdf-eee08345c763', 'ja', 'roora-3-4', 'ルーラ「3!4!」', '1996年発表、混声グループ・ルーラを代表するダンスヒット曲。', '1996年に発表されたルーラの「3!4!」は、同年クローンの「クンタリシャバラ」と夏の歌謡チャート1位を争った曲で、掛け声のようなサビとともに1990年代ダンス歌謡全盛期を象徴する曲に数えられる。', '1996年6月15日発売、ルーラ4集『All System Go』のタイトル曲。タイトルの「3!4!」には、3回転んでも4回目でまた立ち上がるという意味が込められており、作曲家のイ・ヒョンドがメンバーの知人の葬儀の後に低迷していたルーラの再起を助けるために作ったとされる。「星たちの戦争」と呼ばれた1996年歌謡界の激戦の中でも歌謡トップ10で3週連続1位を獲得し、覚えやすい歌詞とメロディからスポーツ大会や学園祭の定番曲となった。近年ではイントロのリズムに合わせて動きを合わせるゲームが放送・SNSで流行している。', '賑やかな応援の掛け声のようにサビを叫ぶ際に使える', NULL, array['3!4!', 'ルーラ サムサ', '룰라 3!4!']::text[], '[]'::jsonb, 'machine', '2026-07-15T15:30:00.191373+00:00', 'claude', 'claude-fable-5', 12, now(), null, null)
insert into public.meme_translations
  (meme_id, locale, localized_slug, title, summary, description, origin, usage_note, caution, aliases, usage_examples, status, source_updated_at, provider, model, prompt_version, translated_at, reviewed_at, reviewed_by)
values
  ('f4b7170c-76d3-4144-a0a5-2bc23db98169', 'ja', 'ses-dream', 'S.E.S.「ドリーム(Dream)」', '1998年発表、S.E.S.のユーロダンス調ヒット曲。', 'S.E.S.の2集タイトル曲「ドリーム」は、当時韓国歌謡界では珍しかったユーロジャンルに挑戦した楽曲で、S.E.S.を代表する曲であり、代表的な振り付けとしても長く記憶されている。', '「ドリーム」(原題Dreams Come True)は、S.E.S.が1998年11月23日に発売した正規2集のタイトル曲である。1996年にフィンランドのガールズグループ、ナイロン・ビートが歌った「Rakastuin mä looseriin」をユ・ヨンジンが編曲し、韓国語詞で生まれ変わらせた曲で、ユジンとシューが歌うスキャットラップパートを原曲になかった構成として新たに追加したのが特徴である。軽快なユーロダンスサウンドとパートを分けて歌う唱法が当時は新鮮に受け止められ、大きな人気を集めた。', '1990年代末のガールズグループヒット曲の代表例として言及できる', NULL, array['Dreams Come True', 'S.E.S. ''드림''']::text[], '[]'::jsonb, 'machine', '2026-07-15T15:30:00.191373+00:00', 'claude', 'claude-fable-5', 12, now(), null, null)
insert into public.meme_translations
  (meme_id, locale, localized_slug, title, summary, description, origin, usage_note, caution, aliases, usage_examples, status, source_updated_at, provider, model, prompt_version, translated_at, reviewed_at, reviewed_by)
values
  ('4ced8917-c746-4d22-bff5-bfc19d01f4fa', 'ja', 'kt-n016-goodnight', 'KT n016「おやすみ、僕の夢見て」', 'イ・ジョンヒョンとチョ・ソンモが共演し国民的CMソングとなったn016携帯電話広告のキャッチコピー。', '2000年のKT n016広告で、イ・ジョンヒョンがチョ・ソンモに向かって「おやすみ、僕の夢見てね」とささやくシーンが、その年の広告業界最大のヒット作に数えられた。愛らしいセリフと2人のスターの相性が相まって、世代を超えて語り継がれるCMフレーズとなった。今でもおやすみの挨拶を茶目っ気たっぷりに引用する際の定番フレーズである。', '2000年、KT n016テレビCM。イ・ジョンヒョン、チョ・ソンモ出演。', 'おやすみの挨拶を可愛らしく伝える際に引用される', NULL, array['イ・ジョンヒョン&チョ・ソンモ n016', 'KT n016 잘자 내꿈꿔']::text[], '[]'::jsonb, 'machine', '2026-07-15T15:30:00.191373+00:00', 'claude', 'claude-fable-5', 12, now(), null, null)
insert into public.meme_translations
  (meme_id, locale, localized_slug, title, summary, description, origin, usage_note, caution, aliases, usage_examples, status, source_updated_at, provider, model, prompt_version, translated_at, reviewed_at, reviewed_by)
values
  ('fcdf42f9-4e06-423e-8ed8-8fec72fa10e1', 'ja', 'mo-tae-bum-vancouver-gold', 'モ・テボム、バンクーバー五輪金メダル', 'ダークホースとしてスピードスケート500mを制した2010年バンクーバー五輪のモ・テボム。', 'モ・テボムは2010年バンクーバー五輪スピードスケート男子500mで、1・2回目のレース合計タイム69秒82で金メダルを獲得した。当時世界ランキング上位だったイ・ギュヒョク、イ・ガンソクに注目が集まっていた中での予想外の優勝であり、大きな話題を呼んだ。小学生時代からの友人であるイ・サンファ、イ・スンフンとともにメダルを獲得し、「スピードスケート三兄弟」と呼ばれてメディアの大きな注目を浴びた。', '2010年バンクーバー五輪スピードスケート男子500m優勝', '韓国スピードスケート全盛期の代表例として引用される。', NULL, array['スピードスケート三兄弟', '모태범 밴쿠버올림픽 금메달']::text[], '[]'::jsonb, 'machine', '2026-07-15T15:30:00.191373+00:00', 'claude', 'claude-fable-5', 12, now(), null, null)
insert into public.meme_translations
  (meme_id, locale, localized_slug, title, summary, description, origin, usage_note, caution, aliases, usage_examples, status, source_updated_at, provider, model, prompt_version, translated_at, reviewed_at, reviewed_by)
values
  ('c2cd3366-1acd-4d9a-866a-542732c80fe8', 'ja', 'molae-barrack-im-yohwan', '隠しバラック(イム・ヨファンの奇襲戦術)', 'イム・ヨファンのトレードマークだった欺瞞戦術用語。', 'イム・ヨファンが相手の偵察を避けてこっそりバラック(兵舎)などの建物を建設し、予想外のタイミングで兵力を繰り出す欺瞞戦術を繰り返し披露したことから定着した用語である。ドロップシップを活用したゲリラ戦とともに、イム・ヨファンの心理戦を代表するスタイルとして挙げられる。1999〜2001年、イム・ヨファンの初期全盛期から語られ始めた。', 'イム・ヨファンの『スタークラフト』初期活動(1999〜2001年)における欺瞞戦術', '相手に気づかれないよう準備して不意を突く戦略を指す際に使用', NULL, array['イム・ヨファンの隠しバラック', '몰래 배럭']::text[], '[]'::jsonb, 'machine', '2026-07-15T15:30:00.191373+00:00', 'claude', 'claude-fable-5', 12, now(), null, null)
insert into public.meme_translations
  (meme_id, locale, localized_slug, title, summary, description, origin, usage_note, caution, aliases, usage_examples, status, source_updated_at, provider, model, prompt_version, translated_at, reviewed_at, reviewed_by)
values
  ('cb1bb417-d6bf-485b-8808-8a036d204f5a', 'ja', 'finkl-eternal-love', 'Fin.K.L.「永遠の愛」', '1999年発表、Fin.K.L.を代表するヒット曲。', '1999年5月発売のFin.K.L.2集『White』のタイトル曲「永遠の愛」は、発売直後から大きな人気を集め、その年のSBS歌謡大典をはじめ各種年末授賞式を席巻した。', '「永遠の愛」はFin.K.L.が1999年5月13日に発売した正規2集『White』のタイトル曲で、キム・ヨンア作詞、チュ・テヨン作曲による楽曲である。発売後、ミュージックバンク、ミュージックキャンプ、人気歌謡など地上波3社の音楽番組すべてで1位を獲得するトリプルクラウンを達成し、1999年末のソウル歌謡大賞とSBS歌謡大典でガールズグループ初の大賞を受賞するなど絶頂の人気を誇った。この曲を機にFin.K.L.は「妖精」というイメージを確立し、1990年代後半を代表するガールズグループとしての地位を築いた。', '1990年代末のガールズグループヒット曲の代表例として言及できる', NULL, array['永遠の愛', '핑클 ''영원한 사랑''']::text[], '[]'::jsonb, 'machine', '2026-07-15T15:30:00.191373+00:00', 'claude', 'claude-fable-5', 12, now(), null, null)
insert into public.meme_translations
  (meme_id, locale, localized_slug, title, summary, description, origin, usage_note, caution, aliases, usage_examples, status, source_updated_at, provider, model, prompt_version, translated_at, reviewed_at, reviewed_by)
values
  ('fbef165a-1f22-4c61-b4ae-94b848228c1c', 'ja', 'pubg-chicken-dinner-kr', 'PUBG「チキン食べた」', '『PUBG: Battlegrounds』の1位勝利メッセージから生まれた「チキン食べた」という表現が流行語になったもの。', '2017年に『PUBG』が韓国で爆発的な人気を博す中、ゲームで1位になった際に表示される韓国語メッセージ(「勝った!今夜の夕食はチキンだ!」という意味の文に、鶏の鳴き声を模した語尾を重ねる言葉遊びが含まれる)に由来し、「チキンを食べた」という表現が日常的な流行語として定着した。その後、ゲーム進行中に退出しようとすると「チキンを諦めますか?」という警告文に変わるようにもなった。', 'ゲーム『PUBG』の勝利メッセージ(2017年韓国での大流行時)', '何かに勝利した際の祝いの表現として使用できる', NULL, array['チキンを食べた', '오늘 저녁은 치킨이닭']::text[], '[]'::jsonb, 'machine', '2026-07-15T15:30:00.191373+00:00', 'claude', 'claude-fable-5', 12, now(), null, null)
insert into public.meme_translations
  (meme_id, locale, localized_slug, title, summary, description, origin, usage_note, caution, aliases, usage_examples, status, source_updated_at, provider, model, prompt_version, translated_at, reviewed_at, reviewed_by)
values
  ('f9c65dc7-9fd1-4dee-b49d-3b14133af280', 'ja', 'tara-bo-peep-cat-dance', 'T-ARA「Bo Peep Bo Peep」猫ダンス', 'T-ARAを一躍トップアイドルに押し上げた2009年冬のヒット曲の猫ダンス。', '2009年冬に発表されたT-ARAの「Bo Peep Bo Peep」は、セクシーながらも愛らしい衣装と中毒性の高いメロディで大きな人気を集め、特にポイント振り付けの「猫ダンス」が話題となった。少女時代とWonder Girlsが二強を成していたガールズグループ市場で、T-ARAを一気にトップクラスへと押し上げた曲と評価されている。', 'コア・コンテンツ・メディア所属T-ARA「Bo Peep Bo Peep」(2009年12月)の振り付け', '2009年のガールズグループの振り付け流行を語る際に', NULL, array['Bo Peep Bo Peep振り付け', '猫ダンス', '티아라 보핍보핍 고양이춤']::text[], '[{"text": "この表情完全に猫ダンスstだ", "situation": "カカオトーク"}, {"text": "ボピボピあの頃本当に大人気だったよね", "situation": "SNSコメント"}]'::jsonb, 'machine', '2026-07-15T15:30:00.191373+00:00', 'claude', 'claude-fable-5', 12, now(), null, null)
insert into public.meme_translations
